from fastapi import APIRouter, Depends, HTTPException, status
from pydantic import BaseModel
import hvac

router = APIRouter(prefix="/kms/keys")

class DecryptionRequest(BaseModel):
    ciphertext: str

@router.post("/{key_name}/decrypt")
async def decrypt_transit_ciphertext(
    key_name: str,
    req: DecryptionRequest,
    key_registry: KeyRegistry = Depends(get_key_registry),
    vault_client: hvac.Client = Depends(get_vault_client),
    user: AuthUser = Depends(get_authenticated_user)
):
    key_metadata = await key_registry.get_key(key_name)
    if not key_metadata:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Encryption key not found")

    if key_metadata.organization_id != user.organization_id:
        raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail="Forbidden: key belongs to another organization")

    try:
        decrypt_response = vault_client.secrets.transit.decrypt_data(
            name=key_name,
            ciphertext=req.ciphertext
        )
        return {
            "key_name": key_name,
            "plaintext_base64": decrypt_response["data"]["plaintext"]
        }
    except hvac.exceptions.VaultError as err:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail=f"KMS decryption error: {err}")
